import{_ as o,c as i,o as e,ag as a}from"./chunks/framework._xRlcm3f.js";const m=JSON.parse('{"title":"哔哩哔哩配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/custom-bilibili.md","filePath":"platforms/custom-bilibili.md","lastUpdated":1790228279000}'),d={name:"platforms/custom-bilibili.md"};function l(r,t,s,c,n,h){return e(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="哔哩哔哩配置指南" tabindex="-1">哔哩哔哩配置指南 <a class="header-anchor" href="#哔哩哔哩配置指南" aria-label="Permalink to &quot;哔哩哔哩配置指南&quot;">​</a></h1><p>通过登录哔哩哔哩的 <strong>Cookie</strong> 发布到哔哩哔哩专栏（opus）。图片默认走平台上传，以 Markdown 发布。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>在浏览器登录哔哩哔哩 <code>https://www.bilibili.com</code>（需可访问创作中心 <code>https://member.bilibili.com</code>）。</li><li>保持该浏览器会话登录状态（后续读取 Cookie 用）。</li><li>无需额外 Token（通过浏览器 Cookie 发布）。</li></ol><h2 id="二、配置" tabindex="-1">二、配置 <a class="header-anchor" href="#二、配置" aria-label="Permalink to &quot;二、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>平台首页</td><td>默认 <code>https://www.bilibili.com/opus</code>，一般不改</td></tr><tr><td>API 地址</td><td>默认 <code>https://api.bilibili.com</code>，一般不改</td></tr><tr><td>Cookie</td><td>点「1 去登录」登录后关闭窗口，再点「2 自动读取 Cookie」；也可展开「手动编辑」直接粘贴</td></tr><tr><td>预览规则</td><td>查看文章链接模板，默认 <code>/[postid]</code>（对应专栏地址 <code>/opus/&lt;id&gt;</code>）</td></tr><tr><td>发布格式</td><td>默认 Markdown</td></tr><tr><td>文集</td><td>发布目标文集（如「远方的灯塔」）；未选择时发布为独立专栏</td></tr><tr><td>图床</td><td>默认「当前平台」（平台图片上传）</td></tr></tbody></table><h2 id="三、验证与发布" tabindex="-1">三、验证与发布 <a class="header-anchor" href="#三、验证与发布" aria-label="Permalink to &quot;三、验证与发布&quot;">​</a></h2><ol><li>点「1 去登录」→ 在弹出的 B 站登录窗完成登录 → <strong>关闭窗口</strong>（触发 Cookie 落盘）→ 回到插件点「2 自动读取 Cookie」→ 检查其余字段 → 点「验证」。</li><li>快速发布 → 选哔哩哔哩 → 发布；发布成功后点「查看文章」打开 <code>https://www.bilibili.com/opus/&lt;id&gt;</code>。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>Cookie 验证失败</strong>：确认浏览器已登录哔哩哔哩且可访问创作中心（member.bilibili.com），重新读取 Cookie。</li><li><strong>图片图床</strong>：默认「当前平台」即可。哔哩哔哩使用平台图片上传，不依赖本机 PicGo 服务。</li><li><strong>发布后在哪里查看</strong>：发布成功后点「查看文章」打开专栏链接，也可在 B 站创作中心 → 专栏管理查看。</li></ul>',10)])])}const p=o(d,[["render",l]]);export{m as __pageData,p as default};
